const MINTAKA_DEC = -0.299095;
const SUBARU_RA = 3.777222;
const SUBARU_DEC = 24.178056;
const M42_RA = 5.588007;
const M42_DEC = -5.3876;
const VEGA_RA = 18.615649;
const VEGA_DEC = 38.783689;
const ALTAIR_RA = 19.846388;
