/** API標高とユーザー高さから内部計算用elevを再計算 */
function recalcElev(type) {
    if (type === 'start') {
        appState.start.elev = appState.startApiElev + appState.startHeight;
    } else {
        appState.end.elev = appState.endApiElev + appState.endHeight;
    }
}

