/** 月齢が基準月齢±許容範囲の範囲内かどうか（月齢はSYNODIC_MONTHで循環） */
function isMoonAgeInRange(moonAge, base, tolerance) {
    const S = SYNODIC_MONTH;
    // 循環を考慮した最短距離
    let diff = Math.abs(moonAge - base);
    if (diff > S / 2) diff = S - diff;
    return diff <= tolerance;
}

