// v20: 第116ラウンド。宙の窓「:写真テクスチャ」(soraPhotoTex)のシード。
// 第3規則「&キー名=既定値」(v1.85.1時点の既定値falseで凍結)+既定値以外用の「&キー名=」
const _QP_SEEDS_V20 = _QP_SEEDS_V19.concat(['&soraPhotoTex=false', '&soraPhotoTex=']);
// v21(第128): 辻メッシュ精度フィルタの新既定「○」の既定値ペア(初期値がx1→o1に変わり、
// 既定のままのURLに&tsujiMeshAccuracy=o1が乗るため)
const _QP_SEEDS_V21 = _QP_SEEDS_V20.concat(['&tsujiMeshAccuracy=o1']);
const _QP_SEED_VERSIONS = [_QP_SEEDS, _QP_SEEDS_V2, _QP_SEEDS_V3, _QP_SEEDS_V4, _QP_SEEDS_V5, _QP_SEEDS_V6, _QP_SEEDS_V7, _QP_SEEDS_V8, _QP_SEEDS_V9, _QP_SEEDS_V10, _QP_SEEDS_V11, _QP_SEEDS_V12, _QP_SEEDS_V13, _QP_SEEDS_V14, _QP_SEEDS_V15, _QP_SEEDS_V16, _QP_SEEDS_V17, _QP_SEEDS_V18, _QP_SEEDS_V19, _QP_SEEDS_V20, _QP_SEEDS_V21];   // 添字+1=版数。最新版でエンコードする
const _QP_PRIME_FROM = 12;   // この版以降は「仮想の先頭&」を足して圧縮する(先頭キーも「&キー名=」の辞書に乗せるため)

function encodeQueryParam(str) {
    if (str === '') return '';
    const version = _QP_SEED_VERSIONS.length;   // 常に最新版の辞書で圧縮
    // v12以降: 仮想の先頭「&」を足してから圧縮する(先頭キーだけ「&」が無く「&キー名=」の辞書に
    // 乗らないのを避ける。復号側が同じ規則で外すので、URLには現れない)
    const bytes = new TextEncoder().encode(version >= _QP_PRIME_FROM ? '&' + str : str);
    // LZW圧縮 (初期辞書=1バイト256種, コード幅9bit開始で辞書拡大に応じて広げる)
    const dict = new Map();
    for (let i = 0; i < 256; i++) dict.set(String.fromCharCode(i), i);
    let nextCode = 256;
    for (const e of _qpSeedEntries(_QP_SEED_VERSIONS[version - 1])) { if (!dict.has(e)) dict.set(e, nextCode++); }
    let width = 9;
    while ((1 << width) < nextCode) width++;   // 初期辞書が512を超える場合は幅を拡げて開始
    const out = [];   // {code, width}
    let w = '';
    for (let i = 0; i < bytes.length; i++) {
        const c = String.fromCharCode(bytes[i]);
        const wc = w + c;
        if (dict.has(wc)) { w = wc; continue; }
        out.push({ code: dict.get(w), width });
        dict.set(wc, nextCode++);
        if (nextCode === (1 << width) + 1) width++;   // 新しいコードが幅に収まらなくなる直前に拡幅
        w = c;
    }
    if (w !== '') out.push({ code: dict.get(w), width });
    // ビットパック → Base64URL (6bit単位)
    let acc = 0, nbits = 0, s = '';
    for (const { code, width: wd } of out) {
        acc = (acc * (1 << wd)) + code;   // 上位詰め
        nbits += wd;
        while (nbits >= 6) {
            nbits -= 6;
            s += _QP_B64[Math.floor(acc / (1 << nbits)) & 63];
            acc = acc % (1 << nbits);
        }
    }
    if (nbits > 0) s += _QP_B64[(acc << (6 - nbits)) & 63];
    return (version >= 2 ? `~${version}~` : '') + s;   // v2以降は辞書版数プレフィックス(v1=無印)
}

function decodeQueryParam(s) {
    try {
        if (!s) return '';
        // 辞書版数プレフィックス(~N~)。無印はv1(レガシーURL)
        let seeds = _QP_SEEDS;
        let version = 1;
        const vm = /^~(\d+)~/.exec(s);
        if (vm) {
            const v = parseInt(vm[1]);
            if (v < 2 || v > _QP_SEED_VERSIONS.length) return null;   // 未知の版(将来の新版URL)は復号不可
            seeds = _QP_SEED_VERSIONS[v - 1];
            version = v;
            s = s.slice(vm[0].length);
            if (!s) return '';
        }
        // Base64URL → ビット列リーダー
        const vals = [];
        for (const ch of s) {
            const v = _QP_B64.indexOf(ch);
            if (v < 0) return null;
            vals.push(v);
        }
        let pos = 0;   // ビット位置
        const total = vals.length * 6;
        const readBits = (n) => {
            if (pos + n > total) return null;
            let r = 0;
            for (let i = 0; i < n; i++) {
                const v6 = vals[(pos / 6) | 0];
                const bit = (v6 >> (5 - (pos % 6))) & 1;
                r = (r << 1) | bit;
                pos++;
            }
            return r;
        };
        // LZW展開
        const dict = [];
        for (let i = 0; i < 256; i++) dict.push(String.fromCharCode(i));
        for (const e of _qpSeedEntries(seeds)) dict.push(e);
        let nextCode = dict.length, width = 9;
        while ((1 << width) < nextCode) width++;   // エンコーダと同一の初期幅
        let code = readBits(width);
        if (code === null) return '';
        let w = dict[code];
        if (w === undefined) return null;
        let res = w;
        while (true) {
            if (nextCode === (1 << width)) width++;   // エンコーダが拡幅した直後のコードに合わせる
            if (pos + width > total) break;           // 端数パディングは無視
            code = readBits(width);
            if (code === null) break;
            let entry;
            if (code < dict.length) entry = dict[code];
            else if (code === nextCode) entry = w + w[0];   // KwKwK ケース
            else return null;
            res += entry;
            dict.push(w + entry[0]); nextCode++;
            w = entry;
        }
        // バイト列 → UTF-8文字列
        const bytes = new Uint8Array(res.length);
        for (let i = 0; i < res.length; i++) bytes[i] = res.charCodeAt(i);
        const text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
        // v12以降: エンコード側が足した仮想の先頭「&」を外す(無ければ壊れたURLとして復号失敗扱い)
        if (version >= _QP_PRIME_FROM) return text[0] === '&' ? text.slice(1) : null;
        return text;
    } catch (_) {
        return null;
    }
}

function buildBaseUrl() {
    return window.location.origin + window.location.pathname;
}

// 日時をdessin仕様フォーマットに変換するヘルパー
function formatDateForUrl(d) {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}${m}${day}`;
}
function formatTimeForUrl(d) {
    return `${String(d.getHours()).padStart(2,'0')}${String(d.getMinutes()).padStart(2,'0')}${String(d.getSeconds()).padStart(2,'0')}`;
}

// ブラウザのタイムゾーンオフセットを+0900形式で返す
function getLocalTimezoneOffsetString() {
    const offset = new Date().getTimezoneOffset(); // JSTなら-540
    const sign = offset <= 0 ? '+' : '-';
    const abs = Math.abs(offset);
    const h = String(Math.floor(abs / 60)).padStart(2, '0');
    const m = String(abs % 60).padStart(2, '0');
    return `${sign}${h}${m}`;
}

// +0900形式をパースして分単位(JSTなら+540)で返す
function parseTimezoneOffsetMinutes(tzString) {
    const match = tzString.match(/^([+-])(\d{2})(\d{2})$/);
    if (!match) return 540; // デフォルトJST
    const sign = match[1] === '+' ? 1 : -1;
    return sign * (parseInt(match[2]) * 60 + parseInt(match[3]));
}

// 共通のURLパラメータを構築するヘルパー。
// profile(第95ラウンド・依頼者指示「URL取得ボタンには、それぞれ、意味があります」):
//   'full'    = 位置情報メニューのURL(宙の辻の画面再現。再現に必要なものを全て詰め込む。
//               第108ラウンドから辻検索/辻メッシュの検索条件も乗せる=検索結果を出した画面も
//               条件ごと再現できる。「発行は絞る、復元は絞らない」の発行側が全部盛り)
//   'tsuji'   = 辻検索/辻メッシュ検索のURL(検索の再現に必要なもの: 地点・表示天体・
//               大気差/気象・天の川の基準点・:除外範囲・:辻オフセット。宙の窓/花火/宙検索/
//               パネル状態/天体色/天体儀表示は発行しない)
//   'soramado'= 宙の窓のURL(窓の再現に必要なもの: 地点・表示天体・宙の窓全項目・花火・
//               天体色/線種・天体儀の表示チェック(窓にも映る)・大気差/気象・天の川の基準点。
//               宙検索/パネル状態/:除外範囲/:辻オフセットは発行しない)
// キーが無い項目は開いた側の既定値のままになる(restoreFromUrlは有るキーだけを適用する)
const _URL_PROFILE_GROUPS = {
    full:     { panels: 1, sora: 1, fw: 1, ss: 1, bodyStyle: 1, atmo: 1, mwBase: 1, mwShow: 1, elevEx: 1, tsujiLine: 1, tsujiCond: 1, tsujiMeshCond: 1 },
    tsuji:    { atmo: 1, mwBase: 1, elevEx: 1, tsujiLine: 1 },
    soramado: { sora: 1, fw: 1, bodyStyle: 1, atmo: 1, mwBase: 1, mwShow: 1 },
};
function buildCommonUrlParams(dateTimeMode = 'fixed', profile = 'full') {
    const inc = _URL_PROFILE_GROUPS[profile] || _URL_PROFILE_GROUPS.full;
    const d = appState.currentDate;
    const params = new URLSearchParams();
    if (dateTimeMode === 'fixed' || dateTimeMode === true) {
        params.set('date', formatDateForUrl(d));
        params.set('time', formatTimeForUrl(d));
        params.set('timeZone', getLocalTimezoneOffsetString());
    } else if (dateTimeMode === 'semi-fixed') {
        // 年を0000にして月日時は固定
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        params.set('date', `0000${mm}${dd}`);
        params.set('time', formatTimeForUrl(d));
        params.set('timeZone', getLocalTimezoneOffsetString());
    }
    params.set('startLat', String(appState.start.lat));
    params.set('startLng', String(appState.start.lng));
    params.set('startApiElv', String(appState.startApiElev));
    params.set('startElv', String(appState.startHeight));
    params.set('endLat', String(appState.end.lat));
    params.set('endLng', String(appState.end.lng));
    params.set('endApiElv', String(appState.endApiElev));
    params.set('endElv', String(appState.endHeight));

    // 表示天体: starIdを複数指定
    const visibleBodies = appState.bodies.filter(b => b.visible);
    visibleBodies.forEach(b => {
        params.append('starId', b.id);
        // My天体の場合は追加情報を付与
        if (b.isCustom) {
            const myStar = appState.myStars.find(s => String(s.id) === b.id);
            if (myStar) {
                params.append('starName', myStar.name);
                params.append('starRa', String(myStar.ra));
                params.append('starDec', String(myStar.dec));
                params.append('starColor', myStar.color);
                params.append('starIsDashed', myStar.isDashed ? '1' : '0');
            }
        }
    });

    // 下部パネル等の表示/非表示状態(画面再現=fullのみ): 辻ライン・標高グラフ・天体儀・宙の窓・辻検索
    if (inc.panels) {
    params.set('dp', appState.isDPActive ? 'true' : 'false');
    params.set('elevation', appState.isElevationActive ? 'true' : 'false');
    params.set('milkyway', appState.isMilkyWayActive ? 'true' : 'false');
    params.set('soramado', appState.isSoramadoActive ? 'true' : 'false');
    params.set('tsujisearch', appState.isTsujiSearchActive ? 'true' : 'false');
    params.set('tsujimesh', appState.isTsujiMeshActive ? 'true' : 'false');
    }

    // 宙の窓メニュー＋コントロールメニューの全項目(full/宙の窓URL)
    if (inc.sora)
    ['soraSensorKey', 'soraAspectW', 'soraAspectH', 'soraOrient', 'soraFocal', 'soraFNumberIdx', 'soraFocusDist',
     'soraFisheye', 'soraFisheyeStrength', 'soraFisheyeShape', 'soraPanorama', 'soraPanoAov',
     'soraPeaking', 'soraTraj', 'soraCenterCross', 'soraTargetCross', 'soraSearchCenter',
     'soraBaseAz', 'soraBaseAlt', 'soraOffsetAz', 'soraOffsetAlt', 'soraViewRange',
     'soraMovInterval', 'soraMovShots', 'soraMovFps', 'soraMovDispStep', 'soraMovImgMb', 'soraMovPlayMode',
     'soraMwBrightness', 'soraElevShade', 'soraSunShade', 'soraExpFormat', 'soraExpW', 'soraExpH',
     'soraGrayscale', 'soraLabelScale', 'smBldg', 'smBldgTex', 'soraPhotoTex'].forEach(k => {   // 末尾4キーは第108ラウンドで発行漏れを解消・soraPhotoTexは第116ラウンド追加
        const v = appState[k];
        params.set(k, typeof v === 'boolean' ? (v ? 'true' : 'false') : String(v));
    });

    // 花火モード(宙の窓メニュー55〜70段目。full/宙の窓URL。打ち上げ点は設定済みの場合のみ)
    if (inc.fw) {
    ['fwEnabled', 'fwElev', 'fwHeight', 'fwRadius', 'fwSize', 'fwMode', 'fwFreq', 'fwSpread', 'fwShowPoint'].forEach(k => {
        const v = appState[k];
        params.set(k, typeof v === 'boolean' ? (v ? 'true' : 'false') : String(v));
    });
    if (appState.fwLat !== null && appState.fwLng !== null) {
        params.set('fwLat', String(appState.fwLat));
        params.set('fwLng', String(appState.fwLng));
    }
    }

    // 宙検索メニューの全項目(デッサン18。fullのみ)。宙検索は封鎖中の予測系機能(第33ラウンド)なので、
    // 公開ビルドではキー自体を発行しない(第97ラウンド・依頼者の精査指摘「ssUnkaiMode=avoidとかあるのですが」)。
    // ?forecast=1の開発時だけ発行する(復元側は従来どおり=発行済みURLのssキーは読める)。
    // 範囲=自動追従(null)の場合は付与しない
    if (inc.ss && FEATURE_FORECAST_ENABLED) {
    ['ssPreset', 'ssWL', 'ssWM', 'ssWH', 'ssMoonMode', 'ssWMoon', 'ssUnkaiMode', 'ssWUnkai', 'ssWLp', 'ssWTr', 'ssObj', 'ssWObj',
     'ssBandNight', 'ssBandTwilight', 'ssBandGhbh', 'ssBandDay', 'ssDays', 'ssInterval', 'ssFan', 'ssStat'].forEach(k => {
        const v = appState[k];
        params.set(k, typeof v === 'boolean' ? (v ? 'true' : 'false') : String(v));
    });
    if (appState.ssRange !== null) params.set('ssRange', String(appState.ssRange));
    }

    // 組込天体の色/線種(第91ラウンド・v16第2弾): 天体毎キーbodyColor<ID>/bodyDash<ID>。
    // 第108ラウンドから常時発行(既定値でも省略しない): 「作者が既定色に戻した」も毎回URLで伝わり、
    // 開いた側の変更色が残らない。既定値のペアは短縮辞書v19が1コードに畳むので、既定のままのURLは
    // 変更したURLより短い(依頼者の採用条件・実測536字<592字)。キー名はリンター(verify124のemitKeys)が
    // 静的に読めるよう配列リテラルで持つ(DEFAULT_BODIESの並び順で色→線種の順に固定)。full/宙の窓URL
    if (inc.bodyStyle)
    ['bodyColorMilkyWay', 'bodyDashMilkyWay', 'bodyColorSun', 'bodyDashSun', 'bodyColorMoon', 'bodyDashMoon',
     'bodyColorMercury', 'bodyDashMercury', 'bodyColorVenus', 'bodyDashVenus', 'bodyColorMars', 'bodyDashMars',
     'bodyColorJupiter', 'bodyDashJupiter', 'bodyColorSaturn', 'bodyDashSaturn', 'bodyColorUranus', 'bodyDashUranus',
     'bodyColorNeptune', 'bodyDashNeptune', 'bodyColorPluto', 'bodyDashPluto', 'bodyColorPolaris', 'bodyDashPolaris',
     'bodyColorMerak', 'bodyDashMerak', 'bodyColorMintaka', 'bodyDashMintaka', 'bodyColorSubaru', 'bodyDashSubaru',
     'bodyColorM42', 'bodyDashM42', 'bodyColorVega', 'bodyDashVega', 'bodyColorAltair', 'bodyDashAltair',
     'bodyColorDeneb', 'bodyDashDeneb', 'bodyColorBetelgeuse', 'bodyDashBetelgeuse', 'bodyColorSirius', 'bodyDashSirius',
     'bodyColorProcyon', 'bodyDashProcyon'].forEach(k => {
        const isColor = k.startsWith('bodyColor');
        const id = k.slice(isColor ? 9 : 8);
        const b = appState.bodies.find(x => x.id === id);
        if (!b) return;
        if (isColor) params.set(k, b.color);
        else params.set(k, b.isDashed ? '1' : '0');
    });

    // 大気差・気象・基本オプション(第88ラウンド・v16 URL第1弾=第81ラウンドで依頼者承認。
    // 第95ラウンドでグループ毎の発行に: 大気差/気象と天の川の基準点=計算に効くので全プロファイル・
    // 天体儀の表示チェック=full/宙の窓(星座線等は窓にも映る)・:除外範囲と:辻オフセット=full/辻検索系)
    if (inc.atmo) {
    params.set('refractionEnabled', appState.refractionEnabled ? 'true' : 'false');
    params.set('meteoP', String(appState.meteo.p));
    params.set('meteoT', String(appState.meteo.t));
    params.set('meteoL', String(appState.meteo.l));
    }
    if (inc.mwBase)
    ['baseOptMwBase', 'mwOffsetAngle'].forEach(k => {
        const v = appState[k];
        params.set(k, typeof v === 'boolean' ? (v ? 'true' : 'false') : String(v));
    });
    if (inc.mwShow)
    ['mwShowBodies', 'mwShowBodyNames', 'mwShowConstFig',
     'mwShowConstBounds', 'mwShowConstNames', 'mwConstNameSort'].forEach(k => {
        const v = appState[k];
        params.set(k, typeof v === 'boolean' ? (v ? 'true' : 'false') : String(v));
    });
    if (inc.elevEx)
    ['elevExcludeEnabled', 'elevExcludeRadius', 'elevExcludeObsRadius'].forEach(k => {
        const v = appState[k];
        params.set(k, typeof v === 'boolean' ? (v ? 'true' : 'false') : String(v));
    });
    if (inc.tsujiLine)
    ['tsujiLineIncludeOffset'].forEach(k => {
        const v = appState[k];
        params.set(k, typeof v === 'boolean' ? (v ? 'true' : 'false') : String(v));
    });

    // 辻検索/辻メッシュの検索条件(第108ラウンド: fullにも乗せる。検索結果を出した画面の共有は
    // 「条件+パネル開閉由来の自動実行」で毎回同じ結果を再計算して再現する)
    if (inc.tsujiCond) _emitTsujiSearchCondParams(params);
    if (inc.tsujiMeshCond) _emitTsujiMeshCondParams(params);

    return params;
}

// URL取得ポップアップダイアログ
let urlPickerMode = null; // 'location' or 'tsuji'

function toggleUrlPanel(type) {
    const picker = document.getElementById('url-picker');
    const fixedLabel = document.getElementById('url-picker-fixed-label');
    const semiFixedLabel = document.getElementById('url-picker-semi-fixed-label');

    const d = appState.currentDate;
    const mm = String(d.getMonth()+1).padStart(2,'0');
    const dd = String(d.getDate()).padStart(2,'0');
    const hh = String(d.getHours()).padStart(2,'0');
    const mi = String(d.getMinutes()).padStart(2,'0');
    const ss = String(d.getSeconds()).padStart(2,'0');

    fixedLabel.textContent = `日時固定(${d.getFullYear()}年${mm}月${dd}日${hh}:${mi}:${ss})`;
    semiFixedLabel.textContent = `日時半固定(アクセス年の${mm}月${dd}日${hh}:${mi}:${ss})`;
    urlPickerMode = type;
    picker.classList.remove('hidden');
}

function closeUrlPicker() {
    document.getElementById('url-picker').classList.add('hidden');
    urlPickerMode = null;
}

/** URL取得共通: 「短いURL」チェックボックス(初期値オン)に従い、
 *  オン=可逆圧縮したqueryキー1つの短いURL / オフ=キー名やキー値がそのままの長いURL を作る。
 *  どちらのURLでも同じ状態を復元できる(restoreFromUrlが両形式を読む)。 */
function buildShareUrl(params) {
    const chk = document.getElementById('url-picker-short');
    const useShort = !chk || chk.checked;
    return buildBaseUrl() + (useShort ? '?query=' + encodeQueryParam(params.toString()) : '?' + params.toString());
}

/** URL取得共通の出口(第95ラウンド): 「:QRコード」チェック(初期値オフ)がオンなら、URL文字列の
 *  代わりにそのURLのQRコード画像をクリップボードへコピーする(スマホのカメラで読む使い方)。 */
function deliverShareUrl(url, subject) {
    const qrChk = document.getElementById('url-picker-qr');
    if (qrChk && qrChk.checked) { copyShareQr(url, subject); return; }
    navigator.clipboard.writeText(url).then(() => {
        alert(`${subject}URLをクリップボードにコピーしました。`);
    }).catch(() => { prompt('URLをコピーしてください:', url); });
}

/** URLのQRコード画像(PNG)を生成してクリップボードへコピーする。
 *  生成はqrcode-generator(MIT・CDN)でローカル処理(通信なし)。誤り訂正はMから始めて、
 *  URLが入り切らない長さならLへ落として再試行する(それでも入らなければ短いURLを案内) */
async function copyShareQr(url, subject) {
    if (typeof qrcode !== 'function') {
        alert('QRコード部品(CDN)が読み込めていません。ネットワーク接続を確認してページを再読み込みしてください。');
        return;
    }
    let qr = null;
    for (const ec of ['M', 'L']) {
        try { const q = qrcode(0, ec); q.addData(url, 'Byte'); q.make(); qr = q; break; } catch (e) {}
    }
    if (!qr) {
        alert('URLが長すぎてQRコードに入りませんでした。「:短いURL」をオンにしてお試しください。');
        return;
    }
    const n = qr.getModuleCount();
    const scale = Math.max(2, Math.min(8, Math.floor(1024 / (n + 8))));
    const margin = scale * 4;   // クワイエットゾーン=4モジュール
    const size = n * scale + margin * 2;
    const cv = document.createElement('canvas');
    cv.width = cv.height = size;
    const c2 = cv.getContext('2d');
    c2.fillStyle = '#FFFFFF'; c2.fillRect(0, 0, size, size);
    c2.fillStyle = '#000000';
    for (let r = 0; r < n; r++) for (let col = 0; col < n; col++)
        if (qr.isDark(r, col)) c2.fillRect(margin + col * scale, margin + r * scale, scale, scale);
    try {
        // ClipboardItemの値はPromiseで渡す(Safariの操作ジェスチャ制約と両対応の作法)
        const blobP = new Promise((res, rej) => cv.toBlob(b => b ? res(b) : rej(new Error('toBlob失敗')), 'image/png'));
        await navigator.clipboard.write([new ClipboardItem({ 'image/png': blobP })]);
        alert(`${subject}QRコードをクリップボードにコピーしました。`);
    } catch (e) {
        console.error('QR clipboard error:', e);
        alert('クリップボードへの画像コピーに失敗しました(お使いのブラウザが画像コピーに未対応の可能性があります)。「:QRコード」をオフにしてURLでご利用ください。');
    }
}

